/**
 * SFCC-83 — the `recentlyViewed` variation's own contract: image-only, every VARIATION_CONFIG
 * flag false, `ZimmProductCardContent` unmounted entirely, with a minimal real `Link` (product
 * name as visually-hidden accessible text) composed directly in index.tsx replacing Content's own
 * name-link as the card's sole keyboard-reachable element. See index.tsx's own module docblock
 * ("recentlyViewed" paragraph) for the full rationale.
 *
 * No dedicated test asserts `ZimmProductCardMedia` receives no `onClick` in this branch — jsdom
 * cannot distinguish "no handler was wired" from "a handler was wired but chose to no-op" without
 * asserting on a specific side effect, and there is no click-passthrough handler in this branch to
 * spy on (unlike the other three variations' `handleMediaClick`, asserted via `mockHistoryPush` in
 * the "Fix I" describe block above). Confirmed instead by code review: the JSX below omits
 * `onClick` entirely for this branch's `ZimmProductCardMedia` call.
 */
describe('ZimmProductCard — recentlyViewed (SFCC-83): image-only, Content unmounted, one hidden-name link', () => {
  test('badge is suppressed even when a badge label is supplied', () => {
    wrap(<ZimmProductCard {...buildCardProps('recentlyViewed')} badge="Runway" />);
    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.badge}"]`)).not.toBeInTheDocument();
  });

  test('hover image-swap does not mount even when hoverImage is supplied', () => {
    wrap(<ZimmProductCard {...buildCardProps('recentlyViewed')} hoverImage={HOVER} />);
    expect(document.querySelector('[data-role="hover-overlay"]')).not.toBeInTheDocument();
  });

  test('ZimmProductCardContent does not render at all, even with Content-relevant props supplied', () => {
    wrap(<ZimmProductCard {...buildCardProps('recentlyViewed')} currentPrice="$100.00" originalPrice="$150.00" />);
    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.content}"]`)).not.toBeInTheDocument();
  });

  /**
   * RESOLVED (ratified by Marcel): an earlier version of this test discovered that the anchor's
   * accessible name was NOT purely the `VisuallyHidden` product name — a descendant `<img>`'s own
   * `alt` text concatenates onto its containing link's accessible name per standard
   * name-from-content computation, so the real computed name was "Natura Dress Zimmermann dress,
   * front", not "Natura Dress" alone. index.tsx now overrides `alt` to `''` on the copies of
   * `primaryImage`/`hoverImage` passed into `ZimmProductCardMedia` in this branch specifically
   * (the standard WCAG technique for a decorative-in-context image inside an already-labelled
   * link), so the accessible name is exactly the product name — this test asserts the exact match
   * again, not the looser leading-substring match the discovery temporarily required.
   */
  test('renders exactly one real, keyboard-reachable link, whose accessible name is exactly the product name', () => {
    wrap(<ZimmProductCard {...buildCardProps('recentlyViewed')} />);
    const links = screen.getAllByRole('link');
    expect(links).toHaveLength(1);
    expect(screen.getByRole('link', { name: 'Natura Dress' })).toHaveAttribute('href', '/product/1');
  });

  /**
   * Tester-flagged must-fix, now closed: `ZimmProductCardMedia`'s gallery mode activates purely
   * off `images.length > 1`, independent of any `VARIATION_CONFIG` flag. Before this fix, a
   * `recentlyViewed` card given a real multi-image `images` array would have nested carousel
   * arrow `<button>`s inside this branch's own wrapping `<Link>` (invalid nested-interactive
   * HTML), let a "Next image" click bubble up and also fire this Link's own PDP navigation (a
   * real double-navigation bug), and concatenated every slide's own un-blanked `alt` text onto
   * the link's accessible name. `index.tsx` now never forwards `images` in this branch at all,
   * regardless of what's passed in — this test proves all three symptoms are gone with a real
   * multi-image input, not just the single-image fixture the tests above use.
   */
  test('a multi-image gallery passed as images never activates gallery mode: no nested buttons, no double-navigation, accessible name stays exactly the product name', async () => {
    mockHistoryPush.mockClear();
    const user = userEvent.setup();
    wrap(<ZimmProductCard {...buildCardProps('recentlyViewed')} images={GALLERY} />);

    // Gallery mode never activates — no carousel arrow buttons, and no button of any kind at all,
    // regardless of image count. This is the direct fix for the nested-interactive-HTML bug.
    expect(screen.queryByRole('button', { name: 'Next image' })).not.toBeInTheDocument();
    expect(screen.queryByRole('button', { name: 'Previous image' })).not.toBeInTheDocument();
    expect(screen.queryAllByRole('button')).toHaveLength(0);

    // Exactly one link, accessible name still exactly the product name — no gallery image's own
    // alt text bleeds onto it, no matter how many images were passed in.
    const links = screen.getAllByRole('link');
    expect(links).toHaveLength(1);
    const link = screen.getByRole('link', { name: 'Natura Dress' });
    expect(link).toHaveAttribute('href', '/product/1');

    // No double-navigation via this organism's own click-passthrough mechanism: clicking the
    // link never calls history.push (the mechanism this file already uses elsewhere to prove
    // that) — there is nothing nested inside it any more that could bubble a second action in.
    await user.click(link);
    expect(mockHistoryPush).not.toHaveBeenCalled();
  });
});

