 * Fix I (SFCC-236, click-passthrough) — behavioural coverage for `handleMediaClick` (index.tsx).
 * Lifting ZimmProductCardMedia above the stretched-link overlay (this recipe's own Fix I, see the
 * "real recipe assertions" block below) fixes the touch-swipe bug but means a plain click on the
 * image no longer reaches that overlay `<a>` — this organism now navigates via
 * `useHistory().push(href)` itself, guarded so the two arrow buttons and the remove/close button
 * (all real <button> descendants of Media) keep doing only their own thing. Same "necessary, not
 * sufficient" caveat as the "KNOWN LIMITATION" docblock above: this proves the CALLBACK WIRING
 * (does the right handler fire, with the right argument, for the right target), not that a real
 * touch swipe geometrically avoids triggering it — that half needs the real-device/Playwright
 * check the plan's own verification section calls for; jsdom performs no real drag-vs-tap
 * distinction to test against.
 */
describe('ZimmProductCard — Fix I: media click passthrough navigates to href, buttons keep their own behaviour', () => {
  beforeEach(() => {
    mockHistoryPush.mockClear();
  });

  test('clicking the image (not a button) navigates via history.push to the card’s href', async () => {
    const user = userEvent.setup();
    wrap(<ZimmProductCard {...buildCardProps('plp')} />);
    await user.click(screen.getByRole('img', { name: PRIMARY.alt }));
    expect(mockHistoryPush).toHaveBeenCalledTimes(1);
    expect(mockHistoryPush).toHaveBeenCalledWith('/product/1');
  });

  // Fix L (CodeRabbit finding on PR #85, verified correct before fixing): a real <a> lets the
  // browser handle a modifier-click or non-primary-button click natively (new tab/window) instead
  // of forcing an in-page navigation — history.push must never fire for any of these, only for a
  // plain, unmodified, primary-button click (already covered above). `fireEvent` (not
  // `userEvent`) is used here deliberately: this asserts the handler's own raw event-property
  // branching (event.metaKey/ctrlKey/shiftKey/altKey/button), not a realistic user gesture.
  test.each([
    ['Cmd/Meta-click', { metaKey: true }],
    ['Ctrl-click', { ctrlKey: true }],
    ['Shift-click', { shiftKey: true }],
    ['Alt-click', { altKey: true }],
    ['a non-primary-button click (e.g. middle-click)', { button: 1 }],
  ])('%s on the image does NOT navigate', (_label, eventInit) => {
    wrap(<ZimmProductCard {...buildCardProps('plp')} />);
    fireEvent.click(screen.getByRole('img', { name: PRIMARY.alt }), eventInit);
    expect(mockHistoryPush).not.toHaveBeenCalled();
  });

  test('clicking a carousel arrow pages the gallery and does NOT navigate', async () => {
    const user = userEvent.setup();
    wrap(<ZimmProductCard {...buildCardProps('plp')} images={GALLERY} />);
    mockScrollTo();
    await user.click(screen.getByRole('button', { name: 'Next image' }));
    expect(screen.getByRole('group', { name: 'Image 2 of 3' })).toBeInTheDocument();
    expect(mockHistoryPush).not.toHaveBeenCalled();
  });

  test('clicking the remove (close) button removes from wishlist and does NOT navigate', async () => {
    const onRemove = vi.fn();
    const user = userEvent.setup();
    wrap(<ZimmProductCard {...buildCardProps('wishlist')} onRemove={onRemove} />);
    await user.click(screen.getByRole('button', { name: 'Remove Natura Dress from wishlist' }));
    expect(onRemove).toHaveBeenCalledTimes(1);
    expect(mockHistoryPush).not.toHaveBeenCalled();
  });
});

describe('ZimmProductCard — VARIATION_CONFIG drives composed-child props (a sample, not exhaustive — full matrix is Media/Content’s own test responsibility)', () => {
  test('home never renders the bag, attributes row or size chips', () => {
    wrap(<ZimmProductCard {...buildCardProps('home')} currentPrice="$100.00" />);
    expect(screen.queryByRole('button', { name: 'Add to bag' })).not.toBeInTheDocument();
    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.sizeChips}"]`)).not.toBeInTheDocument();
  });

  test('wishlist renders the colour/size attributes row', () => {
    wrap(<ZimmProductCard {...buildCardProps('wishlist')} currentPrice="$100.00" />);
    expect(screen.getByTestId('card-content-attributes')).toBeInTheDocument();
  });

  test('plp out-of-stock renders a disabled bag and a notify-me CTA', () => {
    const onNotifyMe = vi.fn();
    wrap(<ZimmProductCard {...buildCardProps('plp')} isUnavailable onNotifyMe={onNotifyMe} />);
    expect(screen.getByRole('button', { name: 'Add to bag' })).toBeDisabled();
    // Fix C: the organism's own recipe hover-gates this button via `[data-card-slot="notifyMe"]`
    // (see zimmProductCard.css.ts docblock point 4) — needs the real attribute present on the
    // real composed tree, not just Content's own isolated test coverage of the same element.
    expect(screen.getByRole('button', { name: 'Notify me' })).toHaveAttribute('data-card-slot', 'notifyMe');
  });

  /**
   * Fix G (full-sweep follow-up visual audit): `bagHiddenOnMobile` is computed in index.tsx from
   * TWO VARIATION_CONFIG fields (`hideBagOnMobile` — PLP's unconditional rule — and
   * `hideBagOnMobileWhenUnavailable` — Wishlist's narrower, stock-status-dependent one) plus
   * `isUnavailable`. Reading it back off `capturedOrganismStyleProps` (populated by this file's
   * own `useMultiStyleConfig` mock — see that mock's own comment) is what actually proves index.tsx
   * combined them correctly; the "real recipe assertions" block below only proves the RECIPE
   * reacts correctly to whatever `hideBagOnMobile` value it's handed, not that index.tsx computed
   * the right one for a given variation x availability combination.
   */
  test.each([
    ['plp', false, true],
    ['plp', true, true],
    ['wishlist', false, false],
    ['wishlist', true, true],
    ['home', false, false],
    ['home', true, false],
  ] as const)(
    'variation=%s, isUnavailable=%s -> hideBagOnMobile=%s passed to the recipe',
    (variation, isUnavailable, expected) => {
      wrap(<ZimmProductCard {...buildCardProps(variation)} isUnavailable={isUnavailable} onNotifyMe={vi.fn()} />);
      expect(capturedOrganismStyleProps.current?.hideBagOnMobile).toBe(expected);
    },
  );

  /**
   * Same capture technique, closing the loop on Fix C's own suppression logic
   * (`hoverHidesPrice`/`hoverRevealsSizeSelector` AND-ed with `!isUnavailable`,
   * `sizeSelectorUnavailable` AND-ed with `isUnavailable`) — previously only ever verified at the
   * recipe-reaction level (a manually-constructed input into `ZimmProductCardRecipe.baseStyle`
   * directly), never proven that index.tsx itself computes that input correctly for a real
   * variation x availability combination.
   */
  test.each([
    ['home', false, { hoverHidesPrice: false, hoverRevealsSizeSelector: false, sizeSelectorUnavailable: false }],
    ['home', true, { hoverHidesPrice: false, hoverRevealsSizeSelector: false, sizeSelectorUnavailable: false }],
    ['plp', false, { hoverHidesPrice: true, hoverRevealsSizeSelector: true, sizeSelectorUnavailable: false }],
    ['plp', true, { hoverHidesPrice: false, hoverRevealsSizeSelector: false, sizeSelectorUnavailable: true }],
    ['wishlist', false, { hoverHidesPrice: true, hoverRevealsSizeSelector: true, sizeSelectorUnavailable: false }],
    ['wishlist', true, { hoverHidesPrice: false, hoverRevealsSizeSelector: false, sizeSelectorUnavailable: true }],
  ] as const)(
    'variation=%s, isUnavailable=%s -> the unavailable-suppression trio resolves to %o',
    (variation, isUnavailable, expected) => {
      wrap(<ZimmProductCard {...buildCardProps(variation)} isUnavailable={isUnavailable} onNotifyMe={vi.fn()} />);
      expect(capturedOrganismStyleProps.current?.hoverHidesPrice).toBe(expected.hoverHidesPrice);
      expect(capturedOrganismStyleProps.current?.hoverRevealsSizeSelector).toBe(expected.hoverRevealsSizeSelector);
      expect(capturedOrganismStyleProps.current?.sizeSelectorUnavailable).toBe(expected.sizeSelectorUnavailable);
    },
  );

  /**
   * Badge: PLP/Wishlist show it (and therefore Recently Viewed Full History, which reuses the
   * `plp` variation); Home suppresses it per Dani Rivett's scope note — driven entirely by
   * `VARIATION_CONFIG.showBadge`, proven here by passing the identical `badge` prop into every
   * variation and checking which ones actually render it.
   */
  test.each([
    ['home', false],
    ['plp', true],
    ['wishlist', true],
  ] as const)('variation=%s -> badge renders: %s', (variation, expectRendered) => {
    wrap(<ZimmProductCard {...buildCardProps(variation)} badge="Runway" />);
    const badgeEl = document.querySelector(`[data-card-slot="${CARD_SLOT.badge}"]`);
    if (expectRendered) {
      expect(badgeEl).toBeInTheDocument();
      expect(screen.getByText('Runway')).toBeInTheDocument();
    } else {
      expect(badgeEl).not.toBeInTheDocument();
    }
  });

  /**
   * Hover image-swap on Home (module docblock's "Hover image-swap on Home" note): Dani Rivett's
   * comment excludes the model-photo hover swap from Home, overriding the AC's unconditional
   * framing — proven here by supplying the identical `hoverImage` prop into every variation and
   * checking which ones actually mount the two-layer crossfade (`ZimmProductCardMedia`'s own
   * `data-role="hover-overlay"`). Home must NOT mount it even though a usable hoverImage was
   * supplied; PLP/Wishlist still must.
   */
  test.each([
    ['home', false],
    ['plp', true],
    ['wishlist', true],
  ] as const)('variation=%s -> hover image-swap mounts: %s', (variation, expectSwap) => {
    wrap(<ZimmProductCard {...buildCardProps(variation)} hoverImage={HOVER} />);
    const overlay = document.querySelector('[data-role="hover-overlay"]');
    if (expectSwap) {
      expect(overlay).toBeInTheDocument();
    } else {
      expect(overlay).not.toBeInTheDocument();
    }
  });
});

/**
 * Real-recipe assertions — bypasses the useMultiStyleConfig mock entirely, same technique as
 * zimmProductCardMedia/index.test.tsx's "Fix 1" block and
 * zimmProductCardContent/index.test.tsx's own real-recipe block. The component-level tests above
 * all render through the flat mock at the top of this file, which cannot see whether the real
 * recipe ever regresses the hover-reveal media query, the stretched-link overlay, or the z-index
 * lift on the interactive controls.
 *
 * These string keys were independently verified by compiling this exact recipe shape through
 * this project's own installed Stylis (v4.2.0 — the same engine Emotion/Chakra invoke at
 * runtime): the plain descendant selectors below resolve exactly as written, scoped under this
 * recipe's own generated class, with no comma-list scoping surprises.
 */
describe('ZimmProductCard — real recipe assertions (bypasses the useMultiStyleConfig mock)', () => {
  test('the stretched-link overlay is unconditional, absolutely positioned, and carries no z-index of its own', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    const after = root[STRETCH_KEY] as Record<string, unknown>;
    expect(after.position).toBe('absolute');
    expect(after.inset).toBe(0);
    expect(Object.prototype.hasOwnProperty.call(after, 'zIndex')).toBe(false);
  });

  test('the content-button lift selector uses position:relative + zIndex:1 — that element is not positioned by its own component recipe', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    const rule = root[CONTENT_LIFT_KEY] as Record<string, unknown>;
    expect(rule.position).toBe('relative');
    expect(rule.zIndex).toBe(1);
  });

  /**
   * Fix 3 (found during the manual real-browser check performed after the round-2 Scorer PASS):
   * this selector used to be `'[data-card-slot="carousel"] button'` with its own
   * `position: 'relative'` — see the docblock's point 2 for why that shape left the arrows
   * unclickable in a real browser despite this exact test previously passing for it. The fix
   * targets the `carousel` WRAPPER, not the buttons inside it, and (same as `close` below) sets
   * only zIndex — the wrapper is already `position: absolute` via ZimmProductCardMedia's own
   * recipe.
   */
  test('the carousel lift selector sets only zIndex, never position — the wrapper is already positioned by ZimmProductCardMedia’s own recipe', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    const carouselLift = root[CAROUSEL_LIFT_KEY] as Record<string, unknown>;
    expect(carouselLift.zIndex).toBe(1);
    expect(Object.prototype.hasOwnProperty.call(carouselLift, 'position')).toBe(false);
  });

  /**
   * Behavioural fix, confirmed against the Jira AC ("when on desktop and the user hovers, then
   * the arrows appear") and live Figma (Carousel is `hidden="true"` on every Default-state
   * instance checked, visible only on the matching Hover-state instance, for both PLP and
   * Wishlist) — see docblock point 6. Unlike every other reveal in this file, this one is NOT
   * gated behind a `ZimmProductCardStyleProps` flag: `baseStyle({})` with no props at all must
   * still emit it, because desktop arrows behave identically across every variation whenever a
   * card has more than one image. `zimmProductCardMedia.css.ts`'s own `carousel` part used to
   * reveal itself unconditionally under its own `[HOVER_CAPABLE_QUERY]` block (a device-
   * CAPABILITY check, making arrows permanently visible on any hover-capable device) — that
   * sub-block is now removed entirely (see that file's own regression guard), so this pair is the
   * only reveal path left for the arrows.
   */
  test('carousel arrows: unconditional hover+focus-visible reveal inside HOVER_CAPABLE_QUERY, present even with no other flags set', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    const hoverBlock = root[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
    // Fix J (SFCC-236): `display: 'flex'` is kept here (unlike every other reveal in this file,
    // which drops `display` entirely) — carousel needs it for its own `justifyContent`/
    // `alignItems` layout, since `zimmProductCardMedia.css.ts`'s own unconditional `display: 'none'`
    // is gone. `clipPath: 'none'` is the actual reveal signal now, added alongside it.
    expect((hoverBlock[HOVER_CAROUSEL_KEY] as Record<string, unknown>).display).toBe('flex');
    expect((hoverBlock[HOVER_CAROUSEL_KEY] as Record<string, unknown>).clipPath).toBe('none');
    expect((hoverBlock[FOCUS_VISIBLE_CAROUSEL_KEY] as Record<string, unknown>).display).toBe('flex');
    expect((hoverBlock[FOCUS_VISIBLE_CAROUSEL_KEY] as Record<string, unknown>).clipPath).toBe('none');
  });

  /**
   * Fix J belt-and-braces (SFCC-236) — see zimmProductCard.css.ts docblock point 6's own Fix J
   * note: once the carousel wrapper's hidden state stops being `display: 'none'` (which removed
   * the whole subtree from hit-testing regardless of any descendant's own `pointerEvents`), its
   * arrow buttons' own unconditional `pointerEvents: 'auto'` (zimmProductCardMedia.css.ts's
   * `arrowButton` part) is no longer guaranteed un-hittable while clipped, so this recipe adds an
   * explicit default-off/reveal-on pair targeting the buttons themselves.
   */
  test('carousel arrow buttons: pointerEvents is none by default and auto only once revealed (Fix J belt-and-braces)', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    expect((root[CAROUSEL_BUTTON_LIFT_KEY] as Record<string, unknown>).pointerEvents).toBe('none');
    const hoverBlock = root[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
    expect((hoverBlock[HOVER_CAROUSEL_BUTTON_KEY] as Record<string, unknown>).pointerEvents).toBe('auto');
    expect((hoverBlock[FOCUS_VISIBLE_CAROUSEL_BUTTON_KEY] as Record<string, unknown>).pointerEvents).toBe('auto');
  });

  /**
   * Fix 1 (Scorer rework round 1): the close-button lift rule used to also set
   * `position: 'relative'`, which is what an earlier version of this exact test asserted for all
   * three lift keys together. That was proven wrong by rendering the real composed tree: Media's
   * own `close` recipe part already sets `position: 'absolute', top: 0, right: 0` on this exact
   * element, and this rule's `.css-root [data-card-slot="close"]` descendant+attribute selector
   * has higher specificity than Media's own single-class rule — so `position: 'relative'` here
   * WON the cascade and knocked the remove button out of its pinned top-right corner into normal
   * flow. The element is already positioned (by Media's own recipe), which is all `zIndex` needs
   * to take effect — a competing `position` value here was never necessary. See the DOM-level
   * proof below (real recipes composed through the real `chakra` factory + `getComputedStyle`)
   * for confirmation the fix actually restores the pinned position, not just that this key's shape
   * looks right in isolation.
   */
  test('the close lift selector sets only zIndex, never position — the element is already positioned by ZimmProductCardMedia’s own recipe', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    const closeLift = root[CLOSE_LIFT_KEY] as Record<string, unknown>;
    expect(closeLift.zIndex).toBe(1);
    expect(Object.prototype.hasOwnProperty.call(closeLift, 'position')).toBe(false);
  });

import { BP } from 'app/theme/components/footerShared';
import { breakpoints } from 'app/theme/foundation/gridSystem';

// Provisional spacing/size values — kept here as named references until the UI designer
// confirms the token in foundation/spacing.ts or foundation/sizes.ts.
//
// SPACE_SECTION is NOT a missing token: --zimm-scale-1200 (48px) already carries the same
// value. Kept as rem here because that foundation alias is px, which does not scale under
// browser zoom (WCAG 1.4.4 — see .claude/rules/overrideStyling.md Units). Collapse onto the var
// once the foundation alias moves to rem.
const SPACE_SECTION = '3rem'; // alias/space/section (48px)
const SIZE_COL_SUB = '20rem'; // alias/size/footer/col-width-subscribe (320px)
const SIZE_COL_MAP = '37.5rem'; // alias/size/footer/col-width-sitemap (600px)

// Design direction (2026-09-01): below this width the site-map columns wrap underneath the
// subscribe section instead of sitting beside it — replaces BP.tablet (768px) as the switch
// point for contentRow/subscribe/links/linksInner below, since 768-946px didn't leave enough
// room for both side by side. em, not px, per .claude/rules/overrideStyling.md Units (media
// queries are one of the few genuinely context-relative em uses). No confirmed Figma frame yet.
const BP_CONTENT_WRAP = '59.125em'; // 946px

// footer.css.ts owns only the footer's own shell — root container, main layout, the
// subscribe/links content row, and the logo band. Subscribe content, the subscribe modal, nav
// columns, contact icons, and the bottom bar each own their own recipe now — see
// zimmSubscribeSection.css.ts, zimmSubscribeModal.css.ts, footerNavColumn.css.ts,
// zimmContactIconRow.css.ts, bottomBar.css.ts.
export const ZimmFooter = {
  parts: ['container', 'main', 'contentRow', 'subscribe', 'links', 'linksInner', 'logo', 'logoButton'],
  baseStyle: {
    // ─── Root container ────────────────────────────────────────────────
    container: {
      backgroundColor: 'var(--zimm-color-bg-05)',
      width: '100%',
      maxWidth: 'var(--zimm-grid-max-width)',
      marginLeft: 'auto',
      marginRight: 'auto',
    },

    // ─── Main layout ───────────────────────────────────────────────────
    // Figma: Content area and Logo area are siblings inside the dark footer.
    main: {
      display: 'flex',
      flexDirection: 'column',
    },

    // Figma mobile Content (node 40000407-22493): px-[32px] py-[48px]
    // Figma tablet/desktop Content (node 40000407-23484): pt-[64px] pb-[48px] px-[40px]
    //
    // Horizontal padding is sourced from the shared --zimm-grid-margin-*/--zimm-grid-max-width
    // tokens (gridSystem.ts) — same values apply to header and the main content area, one place
    // to change all three. It steps at gridSystem.ts's `xl` breakpoint (1280px), independent of
    // the layout switch below (flexDirection/justifyContent/gap), which switches at
    // BP_CONTENT_WRAP (946px) — see the const's own comment for why that isn't BP.tablet.
    contentRow: {
      display: 'flex',
      flexDirection: 'column',
      gap: SPACE_SECTION,
      paddingTop: SPACE_SECTION,
      paddingBottom: SPACE_SECTION,
      paddingLeft: 'var(--zimm-grid-margin-mobile)',
      paddingRight: 'var(--zimm-grid-margin-mobile)',
      [`@media (min-width: ${BP_CONTENT_WRAP})`]: {
        flexDirection: 'row',
        justifyContent: 'space-between',
        gap: 0,
        paddingTop: 'var(--zimm-scale-4xl)',
        paddingBottom: SPACE_SECTION,
      },
      [`@media (min-width: ${breakpoints.xl})`]: {
        paddingLeft: 'var(--zimm-grid-margin-desktop)',
        paddingRight: 'var(--zimm-grid-margin-desktop)',
      },
    },

    // Subscribe column — capped at 320px at every breakpoint
    subscribe: {
      maxWidth: SIZE_COL_SUB,
      [`@media (min-width: ${BP_CONTENT_WRAP})`]: {
        flex: `0 0 ${SIZE_COL_SUB}`,
        maxWidth: 'none',
      },
    },

    // Site-map column — fills remaining space once beside subscribe, fixed 600px at desktop
    links: {
      [`@media (min-width: ${BP_CONTENT_WRAP})`]: {
        flex: 1,
      },
      [`@media (min-width: ${BP.desktop})`]: {
        flex: `0 0 ${SIZE_COL_MAP}`,
      },
    },

    // Figma: flex-wrap while stacked under subscribe (2-col), nowrap once beside it, justify-between on desktop
    linksInner: {
      display: 'flex',
      flexWrap: 'wrap',
      gap: 'var(--zimm-scale-3xl)',
      alignContent: 'flex-start',
      alignItems: 'flex-start',
      // Once columns switch from a fixed 140px to content-sized/auto width (footerNavColumn.css.ts,
      // also BP.tablet), they no longer fill the row on their own — space-between spreads them
      // across the full width instead of leaving them bunched at the left. Superseded by the
      // flex-end/space-between values below once the row is no longer stacked under subscribe.
      [`@media (min-width: ${BP.tablet})`]: {
        justifyContent: 'space-between',
      },
      [`@media (min-width: ${BP_CONTENT_WRAP})`]: {
        flexWrap: 'nowrap',
        gap: 'var(--zimm-scale-3xl)',
        justifyContent: 'flex-end',
      },
      [`@media (min-width: ${BP.tabletWide})`]: {
        gap: 'var(--zimm-scale-5xl)',
      },
      [`@media (min-width: ${BP.desktop})`]: {
        gap: 0,
        justifyContent: 'space-between',
      },
    },
    logo: {
      paddingTop: SPACE_SECTION,
      paddingBottom: SPACE_SECTION,
      paddingLeft: 'var(--zimm-grid-margin-mobile)',
      paddingRight: 'var(--zimm-grid-margin-mobile)',
      display: 'flex',
      flexDirection: 'column',
      justifyContent: 'center',
      alignItems: 'flex-start',
      position: 'relative',
      _before: {
        content: '""',
        position: 'absolute',
        top: 0,
        left: 'var(--zimm-scale-l)',
        right: 'var(--zimm-scale-l)',
        height: 'var(--zimm-border-width-default)',
        background: 'var(--zimm-color-text-inverse)',
      },
      [`@media (min-width: ${BP.tablet})`]: {
        _before: { display: 'none' },
      },
      [`@media (min-width: ${breakpoints.xl})`]: {
        paddingLeft: 'var(--zimm-grid-margin-desktop)',
        paddingRight: 'var(--zimm-grid-margin-desktop)',
      },
    },
    // Wordmark button — a reset, not a look. The logo owns its own geometry, so this only
    // strips the button chrome and supplies the focus ring the anchor-less markup would
    // otherwise lack (WCAG 2.4.7). Matches the contact icons' ring.
    logoButton: {
      display: 'block',
      background: 'none',
      border: 'none',
      padding: 0,
      cursor: 'pointer',
      _focusVisible: {
        outline: 'var(--zimm-border-width-default) solid',
        outlineColor: 'var(--zimm-color-text-inverse)',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },
  },
};

import { breakpoints } from '../foundation/gridSystem';

// Shared between footer's split recipe files (footer.css.ts, footerNavColumn.css.ts,
// bottomBar.css.ts) so a breakpoint or provisional size can't drift between them the way a
// copy-pasted literal would. Not a general-purpose theme module — scope stays footer-only; see
// .claude/rules/overrideStyling.md's co-location guidance for why these no longer live in one
// flat theme/components/footer.ts.

// `tablet` mirrors the confirmed foundation token `breakpoints.md` — imported rather than
// retyped so the two cannot drift apart. `tabletWide` and `desktop` have no foundation
// equivalent yet; `desktop` additionally conflicts with Chakra's lg (62em) and xl (80em), which
// is why every desktop rule using this constant is a raw @media rather than a responsive prop.
// Media queries cannot consume var(), so this is the one deliberate exception to
// theme/components/ otherwise avoiding direct foundation/ imports in favour of --zimm-* CSS vars.
// audit-allow: raw em is correct and permanent here, not a placeholder awaiting a token —
// overrideStyling.md's Units section documents breakpoints as one of the few genuinely
// context-relative uses of em, deliberately outside the var(--zimm-*) scale system.
export const BP = {
  tablet: breakpoints.md, // Figma: alias/breakpoint/tablet — 768px
  tabletWide: '53.75em', // Figma: alias/breakpoint/tablet-wide — 860px (no foundation equivalent)
  desktop: '64em', // Figma: alias/breakpoint/desktop — 1024px (≠ Chakra lg=62em / xl=80em)
} as const;

// alias/size/footer/col-width-nav (140px). Provisional — kept as a named rem reference until
// the UI designer confirms it in foundation/sizes.ts. Used by both the nav column's own width
// (footerNavColumn.css.ts) and the bottom bar's mobile legal-link width (bottomBar.css.ts) — the
// two must match or the legal links stop lining up with the columns above them.
