1	import React from 'react';
2	import { chakra, useStyleConfig } from '@chakra-ui/react';
3	import { isSafeHref } from 'app/utils/safeHref';
4	
5	type ZimmLinkBaseProps = {
6	  label: string;
7	  size?: 'large' | 'small';
8	};
9	
10	type ZimmAnchorLinkProps = ZimmLinkBaseProps & {
11	  href: string;
12	  onClick?: () => void;
13	};
14	
15	type ZimmButtonLinkProps = ZimmLinkBaseProps & {
16	  href?: never;
17	  onClick: () => void;
18	};
19	
20	/** Props union — href makes it an anchor; omitting href requires onClick (button semantics). */
21	export type ZimmLinkProps = ZimmAnchorLinkProps | ZimmButtonLinkProps;
22	
23	/**
24	 * Atom — underlined text link rendered in two sizes (Large/Small).
25	 * Renders as `<a>` when `href` is provided, `<button>` otherwise.
26	 * All visual states live in `zimmLink.css.ts`.
27	 */
28	export const ZimmLink = (props: ZimmLinkProps) => {
29	  const { label, size = 'large', onClick } = props;
30	  const styles = useStyleConfig('ZimmLink', { size: size === 'small' ? 'sm' : 'lg' });
31	
32	  if ('href' in props && isSafeHref(props.href)) {
33	    return (
34	      <chakra.a href={props.href} onClick={onClick} __css={styles}>
35	        {label}
