import { FONT_MEDIUM, FONT_REGULAR, FONT_SERIF } from './fonts';

// Typography scale primitives — deduplicated from the 22 Handover text styles below.
// zimmTokens.ts's --zimm-font-size-*/lineheight-*/letterspacing-* entries read from
// here too. Naming matches those --zimm-* suffixes.
export const fontSizes = {
  md: '1.5rem', // 24px
  xs: '1rem', // 16px
  '2xs': '0.875rem', // 14px
  '3xs': '0.75rem', // 12px
  '4xs': '0.625rem', // 10px
} as const;

export const lineHeights = {
  md: '2rem', // 32px
  xs: '1.5rem', // 24px
  '2xs': '1.125rem', // 18px
  '3xs': '1rem', // 16px
  '4xs': '0.875rem', // 14px
} as const;

export const letterSpacings = {
  sm: '0',
  xs: '-0.0075rem', // -0.12px
  // Only used by linkLg — still a named token rather than a raw literal so it can't
  // drift out of sync with globalStyles.ts's zimmTextLinkLg.
  '2xs': '-0.00875rem', // -0.14px
  footer: '0.025rem', // 0.4px
} as const;

export const fontWeights = {
  medium: '500',
  regular: '400',
} as const;

// Named text styles — source: Zimmermann Design System 2026 (Handover tokens/typography.css)
// Token name → fontFamily / fontWeight / fontSize / lineHeight / letterSpacing / transform
export const textStyles = {
  // ---- Headings ----
  // ZIM/h1-strong (.zimm-text-h1-strong): 500 weight, uppercase
  heading1Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.md,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights.md,
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ZIM/h1 (.zimm-text-h1): 400 weight, uppercase
  heading1: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes.md,
    fontWeight: fontWeights.regular,
    lineHeight: lineHeights.md,
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ZIM/h2-strong (.zimm-text-h2-strong)
  heading2: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.md,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights.xs,
    letterSpacing: letterSpacings.sm,
  },
  // ZIM/h3-strong (.zimm-text-h3-strong)
  heading3: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.xs,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.xs,
    textTransform: 'uppercase' as const,
  },
  // ---- Body ----
  // ZIM/body1-strong (.zimm-text-body1-strong)
  body1Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.xs,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights.xs,
    letterSpacing: letterSpacings.xs,
  },
  // ZIM/body1 (.zimm-text-body1)
  body1: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes.xs,
    fontWeight: fontWeights.regular,
    lineHeight: lineHeights.xs,
    letterSpacing: letterSpacings.xs,
  },
  // ZIM/body2-strong (.zimm-text-body2-strong)
  body2Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.xs,
  },
  // ZIM/body2 (.zimm-text-body2)
  body2: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.regular,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.sm,
  },
  // ---- Mobile body ----
  // ZIM/Mobile/Body1-strong (.zimm-text-mobile-body1-strong)
  mobileBody1Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.xs,
  },
  // ZIM/Mobile/Body1 (.zimm-text-mobile-body1)
  mobileBody1: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes['2xs'],

// Spacing scale — source of truth: Figma node 2081:52901 (Design-Workspace > Spacing)
// Added to theme.space via extendTheme — Chakra's numeric defaults are preserved.
// Values are in rem so spacing scales with a user's root font-size / browser zoom
// (WCAG 1.4.4). Border widths (below) intentionally stay in px: hairline geometry
// shouldn't scale with zoom.

// prettier-ignore
export const spacing = {
  '3xs': '0.125rem', // 2px
  '2xs': '0.25rem',  // 4px
  xs:    '0.5rem',   // 8px
  s:     '0.75rem',  // 12px
  m:     '1rem',     // 16px
  l:     '1.25rem',  // 20px
  xl:    '1.5rem',   // 24px
  '2xl': '2rem',     // 32px
  '3xl': '2.5rem',   // 40px
  '4xl': '4rem',     // 64px
  '5xl': '5rem',     // 80px
  '6xl': '8rem',     // 128px
  '7xl': '10rem',    // 160px
} as const;

// Border widths — source of truth: Handover tokens/spacing.css (--zimm-border-width-default).
// Registered as theme.borderWidths; the CSS-var twin already exists in zimmTokens.ts.
export const borderWidths = {
  default: '1px',
} as const;

// Focus-ring outline offsets — hairline geometry, stays px like border widths above.
// `secondary` clears the 1px border on the secondary button variant (Handover
// button.md §focus) — the name describes that variant, not a generic scale step,
// since nothing else currently needs a third offset value.
export const focusRingOffsets = {
  default: '2px',
  secondary: '3px',
} as const;

// Icon sizes — source: Zimmermann Design System 2026 (Handover tokens.md § Icon Sizes)
//
// Deliberately NOT registered as `theme.sizes`. Chakra's `sizes.lg` is 32rem and
// backs every `w`/`h`/`boxSize` token across the base retail-react-app, so
// remapping these names would resize base components. Import these constants
// directly instead — the same pattern component overrides already use for
// FONT_MEDIUM: `<Icon boxSize={iconSizes.lg} />`.
export const iconSizes = {
  xl: '24px',
  lg: '20px',
  md: '16px',
  sm: '12px',
} as const;

// Action (button) sizing — source: Handover tokens/spacing.css (--zimm-size-action-*).
// The CSS-var twins already exist in zimmTokens.ts. These are the Handover-correct
// values; zimmButton.css.ts (the single source of truth for actual button styling — no
// .zimm-btn-* class duplicates it) currently uses different prototype values for
// height (BTN_HEIGHT_LG/SM), flagged there pending UI-designer sign-off.
export const actionSizes = {
  height: {
    lg: '52px',
    md: '40px',
  },
  paddingX: {
    lg: '32px',
    md: '20px',
  },
  gap: '16px',
} as const;

// Mega-menu sizing — source: Zimmermann Design System 2026, Figma node 40002429:7215
// (two-column "Expanded Menu" Nav Group, confirmed against SFCC-883).
export const megaMenuSizes = {
  twoColumnMaxWidth: '700px',
} as const;

