import { render, screen } from '@testing-library/react';
import { IntlProvider } from 'react-intl';
import { MemoryRouter } from 'react-router-dom';
import { RECENTLY_VIEWED_RAIL_MAX_ITEMS } from 'app/constants';
import { ZimmRecentlyViewedRail } from './index';
import type { ZimmProductCardProps } from '../zimmProductCard';

vi.mock('@chakra-ui/react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
  return {
    ...actual,
    useMultiStyleConfig: () => ({
      // ZimmRecentlyViewedRail (this component's own recipe).
      container: {},
      header: {},
      seeAllLink: {},
      group: {},
      card: {},
      // ZimmProductCard.
      root: {},
      // ZimmProductCardMedia.
      scrollContainer: {},
      slide: {},
      image: {},
      hoverSwapBase: {},
      hoverSwapOverlay: {},
      badge: {},
      badgeLabel: {},
      close: {},
      carousel: {},
      arrowButton: {},
      indicatorWrapper: {},
    }),
  };
});

